{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Isocorydine, a related alkaloid with a tertiary amine and similar CNS-drug-like properties, was detected in rat brain within 10 minutes of administration, directly demonstrating effective BBB crossing in a chemically relevant class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tylocrebrine, a related alkaloid, showed rapid brain accumulation and an AUCbrain of 2.1 µg·h/mL in mice, supporting meaningful CNS access for alkaloid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Blonanserin, a CNS-active small molecule with moderate lipophilicity and a basic amine, achieved a human brain/plasma ratio of 3.38 by PET, supporting good BBB penetration for this physicochemical profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Demethyleneberberine, a related protoberberine alkaloid, was detected in rat brain after oral dosing (267.56 ng/g), demonstrating that even more polar alkaloids can achieve measurable CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Consistent positive BBB evidence from multiple related alkaloids and CNS-active molecules, together with favorable passive permeability properties, supports meaningful CNS access; no contradictory experimental record was identified.",
  "evidence_gaps": [
    "No direct experimental brain/plasma or CSF measurement for the query molecule itself.",
    "No transporter (P-gp/BCRP) efflux data for the query; the efflux risk is only a computational prior.",
    "Most supporting records are from rodents or different chemical scaffolds; human PET evidence is from a different CNS drug class.",
    "Reported brain concentrations for some analogues are modest and do not quantify unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

